(async () => {
  const basePath = "<방>/home/일감";

  // 1) 표 폴더 안의 파일 목록
  const tableListRes = await t5.call("local.file", { action: "list", path: `${basePath}/표`, limit: 500 });
  const tableFiles = tableListRes.items || [];

  // 2) "지난달" 표로 보이는 파일 고르기: 파일명에 '지난달' 또는 '2026-07' 같은 최근 월 표시가 있는지 확인
  //    편의상 '지난달' 또는 '7월' 또는 '2026-07' 이라는 단어가 들어간 첫 번째 TSV/CSV/엑셀 파일을 지난달 표라고 가정한다
  const candidates = tableFiles.filter(f => f.kind === "file");
  const patterns = ["지난달", "저번달", "7월", "2026-07", "2026_07"];
  let targetFile = null;
  for (const f of candidates) {
    const name = f.name;
    if (patterns.some(p => name.includes(p))) {
      targetFile = f;
      break;
    }
  }

  if (!targetFile) {
    return { ok: false, summary: "표 폴더에서 지난달 표로 추정되는 파일을 못 찾았어요.", result: { tried: candidates.map(c => c.name) } };
  }

  const targetPath = `${basePath}/표/${targetFile.name}`;

  // 3) 파일 읽기
  const readRes = await t5.call("local.file", { action: "read", path: targetPath, limit: 200000 });
  const text = readRes.text;
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length === 0) {
    return { ok: false, summary: "지난달 표 파일이 비어 있어요.", result: { path: targetPath } };
  }

  const header = lines[0].split(/\t|,/); // tsv 또는 csv 둘 다 지원

  // 열 이름 인덱스 찾기 (A/B/C 구분, 동부, 서부, 환불)
  function findIndex(names) {
    // names: possible header labels
    for (let i = 0; i < header.length; i++) {
      const h = header[i].trim();
      if (names.includes(h)) return i;
    }
    return -1;
  }

  const idxCategory = findIndex(["구분", "상품", "A/B/C", "카테고리"]);
  const idxEast = findIndex(["동부", "동부매출", "동부 매출"]);
  const idxWest = findIndex(["서부", "서부매출", "서부 매출"]);
  const idxRefund = findIndex(["환불", "환불액", "환불 금액"]);

  if (idxCategory < 0 || idxEast < 0 || idxWest < 0 || idxRefund < 0) {
    return { ok: false, summary: "열 이름(구분/동부/서부/환불)을 찾지 못했어요.", result: { header } };
  }

  // 4) A/B/C별 순매출 집계
  const totals = { A: 0, B: 0, C: 0 };

  function toNumber(v) {
    if (typeof v !== "string") return 0;
    const cleaned = v.replace(/,/g, "").trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  }

  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(/\t|,/);
    if (cols.length <= Math.max(idxCategory, idxEast, idxWest, idxRefund)) continue;
    const cat = cols[idxCategory].trim();
    if (!["A", "B", "C"].includes(cat)) continue;
    const east = toNumber(cols[idxEast]);
    const west = toNumber(cols[idxWest]);
    const refund = toNumber(cols[idxRefund]);
    const net = east + west - refund;
    totals[cat] += net;
  }

  // 5) TSV 내용 만들기
  const outLines = ["구분\t순매출", `A\t${totals.A}`, `B\t${totals.B}`, `C\t${totals.C}`];
  const outText = outLines.join("\n");

  // 6) 파일 저장: 일감/보고/지난달-순매출.tsv
  const outPath = `${basePath}/보고/지난달-순매출.tsv`;
  await t5.call("local.file", { action: "write", path: outPath, text: outText, source: targetPath, evidenceRows: [
    { source: targetPath, quote: header.join("\t") }
  ]});

  return { ok: true, summary: "지난달 표에서 A/B/C 순매출을 계산해 저장했어요.", result: { totals, outPath, source: targetPath } };
})().then(r => { console.log(JSON.stringify(r, null, 2)); });

